(() => {
  let testState = 'idle'; // idle, waiting, stimulus, finished
  let stimulusTimestamp = 0;
  let timeoutId = null;
  const trials = [];

  const stageEl = document.getElementById('stimulus-stage');
  const textEl = document.getElementById('stimulus-text');
  const trialCountEl = document.getElementById('trial-count');
  const statMeanEl = document.getElementById('stat-mean');
  const statMinEl = document.getElementById('stat-min');
  const statMaxEl = document.getElementById('stat-max');
  const statStdDevEl = document.getElementById('stat-stddev');
  const statTierBadgeEl = document.getElementById('stat-tier-badge');
  const resetBtn = document.getElementById('reset-trials-btn');
  const fpsCounterEl = document.getElementById('fps-counter');

  // 1. Refresh Rate Counter via requestAnimationFrame
  let frameCount = 0;
  let lastFpsTime = performance.now();
  function measureFps(now) {
    frameCount++;
    if (now - lastFpsTime >= 1000) {
      const hz = Math.round((frameCount * 1000) / (now - lastFpsTime));
      fpsCounterEl.textContent = hz + ' Hz';
      return;
    }
    requestAnimationFrame(measureFps);
  }
  requestAnimationFrame(measureFps);

  function setStage(state) {
    testState = state;
    if (state === 'idle') {
      stageEl.className = 'relative w-full h-64 rounded-2xl border-2 border-dashed border-slate-300 bg-slate-50 flex flex-col items-center justify-center p-6 text-center cursor-pointer select-none transition-colors duration-150';
      textEl.innerHTML = '<span class="text-lg font-bold text-slate-800 block">Click Here or Press Space to Begin</span><span class="text-xs text-slate-500 block">When stage turns bright green, click or press Space as fast as possible.</span>';
    } else if (state === 'waiting') {
      stageEl.className = 'relative w-full h-64 rounded-2xl border-2 border-amber-400 bg-amber-50 flex flex-col items-center justify-center p-6 text-center cursor-pointer select-none transition-colors duration-150';
      textEl.innerHTML = '<span class="text-lg font-bold text-amber-900 block">Wait for Green...</span><span class="text-xs text-amber-700 block">Keep fingers ready on Space or Mouse.</span>';
    } else if (state === 'stimulus') {
      stageEl.className = 'relative w-full h-64 rounded-2xl border-2 border-emerald-500 bg-emerald-500 flex flex-col items-center justify-center p-6 text-center cursor-pointer select-none transition-colors duration-75 text-white';
      textEl.innerHTML = '<span class="text-2xl font-black text-white block uppercase tracking-wider">NOW! CLICK OR PRESS SPACE</span>';
    } else if (state === 'too_early') {
      stageEl.className = 'relative w-full h-64 rounded-2xl border-2 border-rose-400 bg-rose-50 flex flex-col items-center justify-center p-6 text-center cursor-pointer select-none transition-colors duration-150';
      textEl.innerHTML = '<span class="text-lg font-bold text-rose-900 block">Too Early!</span><span class="text-xs text-rose-700 block">Click to try again.</span>';
    }
  }

  function updateStats() {
    trialCountEl.textContent = trials.length + ' / 5';
    if (trials.length === 0) {
      statMeanEl.textContent = '-- ms';
      statMinEl.textContent = '--';
      statMaxEl.textContent = '--';
      statStdDevEl.textContent = '--';
      statTierBadgeEl.className = 'p-3 rounded-xl border border-slate-200 bg-white text-xs font-medium text-slate-700';
      statTierBadgeEl.textContent = 'Complete at least 3 trials to evaluate display responsiveness.';
      return;
    }

    const sum = trials.reduce((a, b) => a + b, 0);
    const mean = sum / trials.length;
    const min = Math.min(...trials);
    const max = Math.max(...trials);
    const variance = trials.reduce((acc, v) => acc + Math.pow(v - mean, 2), 0) / trials.length;
    const stdDev = Math.sqrt(variance);

    statMeanEl.textContent = mean.toFixed(1) + ' ms';
    statMinEl.textContent = min.toFixed(1) + ' ms';
    statMaxEl.textContent = max.toFixed(1) + ' ms';
    statStdDevEl.textContent = stdDev.toFixed(1) + ' ms';

    if (trials.length >= 3) {
      if (mean < 210) {
        statTierBadgeEl.className = 'p-3 rounded-xl border border-emerald-200 bg-emerald-50 text-xs font-bold text-emerald-900';
        statTierBadgeEl.textContent = 'Ultra-Responsive (Gaming Mode Active & Low Processing Overhead)';
      } else if (mean < 260) {
        statTierBadgeEl.className = 'p-3 rounded-xl border border-indigo-200 bg-indigo-50 text-xs font-bold text-indigo-900';
        statTierBadgeEl.textContent = 'Optimal (Standard Low-Latency Display Profile)';
      } else if (mean < 330) {
        statTierBadgeEl.className = 'p-3 rounded-xl border border-amber-200 bg-amber-50 text-xs font-bold text-amber-900';
        statTierBadgeEl.textContent = 'Moderate Latency (Television post-processing filters may be active)';
      } else {
        statTierBadgeEl.className = 'p-3 rounded-xl border border-rose-200 bg-rose-50 text-xs font-bold text-rose-900';
        statTierBadgeEl.textContent = 'High Processing Latency (Enable Game Mode / ALLM in TV Settings)';
      }
    }
  }

  function handleInteraction() {
    if (testState === 'idle' || testState === 'too_early') {
      setStage('waiting');
      const delayMs = 1500 + Math.random() * 2500;
      timeoutId = setTimeout(() => {
        stimulusTimestamp = performance.now();
        setStage('stimulus');
      }, delayMs);
    } else if (testState === 'waiting') {
      clearTimeout(timeoutId);
      setStage('too_early');
    } else if (testState === 'stimulus') {
      const reactionTime = performance.now() - stimulusTimestamp;
      trials.push(reactionTime);
      updateStats();
      setStage('idle');
      textEl.innerHTML = `<span class="text-lg font-bold text-slate-800 block">Result: ${reactionTime.toFixed(1)} ms</span><span class="text-xs text-slate-500 block">Click or press Space to take another trial.</span>`;
    }
  }

  stageEl.addEventListener('click', handleInteraction);
  window.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
      // Only prevent default if target is not an input
      if (['INPUT', 'TEXTAREA'].includes(document.activeElement?.tagName)) return;
      e.preventDefault();
      handleInteraction();
    }
  });

  resetBtn.addEventListener('click', () => {
    trials.length = 0;
    clearTimeout(timeoutId);
    setStage('idle');
    updateStats();
  });

  updateStats();
})();
